[Form]
public class TFMFeedbackPart extends FormRun
{

    public GlobalObjectCacheScope feedBackCacheScope = 'FormPartCacheTest';
    protected SysGlobalObjectCache sgoc;

}

/// <summary>
///
/// </summary>
public void run()
{
    super();
    if(!sgoc)
    {
        sgoc = new SysGlobalObjectCache();
    }

    container cacheValue = sgoc.find(element.feedBackCacheScope, ['cacheValueKey']);
    if(!cacheValue)
    {
        sgoc.insert(element.feedBackCacheScope, ['cacheValueKey'], [10]);
    }

    element.design().viewEditMode(ViewEditMode::Edit);
}

/// <summary>
///
/// </summary>
public display str FormDisplayOperationMode()
{
    TFMPageOrderListConfiguration conf = TFMPagesProvider::getAllPages().getPage('Receive').getConfiguration();
    str value = enum2Str(conf.parmOperationMode());

    value = value + ' ' + int2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()));
    return value;
}

public display str FormDisplayAutomaticAcceptOnOpen()
{
    TFMPageOrderListConfiguration conf = TFMPagesProvider::getAllPages().getPage('Receive').getConfiguration();
    str value = conf.parmAutomaticAcceptOnOpen() ? 't' : 'f';
    value = value + ' ' + int2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()));
    return value;
}

public display str FormDisplayCacheValue()
{
    if(!sgoc)
    {
        sgoc = new SysGlobalObjectCache();
    }
    container cacheValue = sgoc.find(element.feedBackCacheScope, ['cacheValueKey']);
    str value = conPeek(cacheValue, 1);
    value = value + ' ' + int2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()));
    return value;
}

public void clicked()
{
    Map parms = new Map(Types::String, Types::String);
    str callerName= element.args().callerName();
    //TFMTestFeedback	helpEnum = TFMHelper::EnumSymbol2Value(enumNum(TFMTestFeedback),feedbacktype.getText(FeedbackType.selection()));

    super();
    parms.insert('reportType',FeedbackType.valueStr());
    parms.insert('message',FeedbackText.text());
    parms.insert('occurred',strFmt('%1',DateTimeUtil::utcNow()));
    parms.insert('formName',callerName);
    parms.insert('user',curUserId());
    SysEmailTable::sendMail('Alert', 'en-us', 'gl@taskletfactory.com',parms);
    SysEmailTable::sendMail('Alert', 'en-us', 'pb@taskletfactory.com',parms);
    FeedbackText.text('');
    Info('Tak for hjælpen');
}

        /// <summary>
        ///
        /// </summary>
        public void clicked()
        {
            if (Box::okCancel("@TFM:Areyousureyouwanttodeleteallthes",DialogButton::Cancel) != DialogButton::Ok)
            {
                return;
            }
            Map                         models = TFMExportSetup::getTables();
            MapEnumerator				mEnum = models.getEnumerator();
            Map							tables;
            MapEnumerator				tEnum;
            TableName					tName;
            Common						common;
            super();

			while (Menum.moveNext())
            {
                tables = mEnum.currentValue();
                tEnum = tables.getEnumerator();
                while (tEnum.moveNext())
                {
                    tName = tEnum.currentKey();
                    common = new SysDictTable(TableName2id(tName)).makeRecord();
                    common.skipDataMethods(true);
                    delete_from common;
                }
            }

        }

/// <summary>
///
/// </summary>
public void clicked()
{
    super();
    if(!sgoc)
    {
        sgoc = new SysGlobalObjectCache();
    }
    container cacheValue = sgoc.find(element.feedBackCacheScope, ['cacheValueKey']);
    if(!cacheValue)
    {
        sgoc.insert(element.feedBackCacheScope, ['cacheValueKey'], [10]);
    } 
    else
    {
        int value = str2Int(conPeek(cacheValue, 1));
        value++;
        sgoc.insert(element.feedBackCacheScope, ['cacheValueKey'], [value]);
    }
    FormStringControlCacheValue.update();
}

/// <summary>
///
/// </summary>
public void clicked()
{
    super();
    if(!sgoc)
    {
        sgoc = new SysGlobalObjectCache();
    }
    sgoc.clear(feedBackCacheScope);
    FormStringControlCacheValue.update();
}
